// import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { AIToolbarProps } from "./ai-toolbar.types";

import { type CSSObject, keyframes } from "@emotion/react";
import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "AIToolbar";

const shimmerSlide = keyframes`
  0% {
    background-position: 200% center, 0 0;
  }
  100% {
    background-position: -200% center, 0 0;
  }
`;

// Generate child element class names for the component, should match available style slots
export const AIToolbarClasses = {
  root: "exp-textura_ai-toolbar",
  trigger: "exp-textura_ai-toolbar_trigger",
  triggerLeading: "exp-textura_ai-toolbar_trigger_leading",
  triggerTrailing: "exp-textura_ai-toolbar_trigger_trailing",
  content: "exp-textura_ai-toolbar_content",
  text: "exp-textura_ai-toolbar_text",
  textContent: "exp-textura_ai-toolbar_text_content",
  icon: "exp-textura_ai-toolbar_icon",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: AIToolbarProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<AIToolbarProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  return {
    position: "relative",
    display: "flex",
    flexDirection: "column",
    boxSizing: "border-box",
    transition: "all 0.4s cubic-bezier(0.25, 1, 0.5, 1)", // Smooth easeOutQuart
    zIndex: 100,
    boxShadow: theme.dropShadow.lg,
    width: theme.toRem(500),
    minHeight: theme.toRem(44),
    ...theme.typography.body.md,

    '&[data-thinking="true"][data-state="collapsed"]': {
      overflow: "visible",
      backgroundClip: "padding-box",

      // Layer 1: The "Glow" + "Shimmer" (Bottom)
      "&::before": {
        content: '""',
        position: "absolute",
        inset: -2,
        zIndex: -1,
        borderRadius: "inherit",
        backgroundImage: `
            linear-gradient(90deg, transparent 0%, transparent 35%, rgba(255,255,255,0.8) 50%, transparent 65%, transparent 100%),
            linear-gradient(90deg, ${theme.color.brand.primary.purple}, ${theme.color.brand.tertiary.pink100})
          `,
        backgroundSize: "200% 100%, 100% 100%",
        animation: `${shimmerSlide} 3s linear infinite`,
        filter: "blur(1px)",
      },

      // Layer 2: The "White Background" (Middle)
      "&::after": {
        content: '""',
        position: "absolute",
        inset: 0,
        zIndex: -1,
        borderRadius: "inherit",
        backgroundColor: theme.color.background.default,
      },
    },

    '&[data-thinking="true"][data-state="expanded"]': {
      overflow: "hidden",
    },

    '&[data-thinking="true"]': {
      ...styleSlots?.thinking,
    },

    [`.${AIToolbarClasses.trigger}`]: {
      position: "absolute",
      top: 0,
      left: 0,
      zIndex: 2,
      display: "flex",
      alignItems: "center",
      width: "100%",
      height: theme.toRem(44),
      minHeight: theme.toRem(44),
      paddingBlock: 0,
      cursor: "pointer",
      borderRadius: theme.toRem(22),
      transition: "opacity 0.2s ease-in-out",
      backgroundColor: theme.color.background.default,
      color: theme.color.content.weak,
      ...theme.typography.body.md,

      "&:focus-visible": {
        ...theme.focusRing,
      },

      [`&:has(.${AIToolbarClasses.triggerLeading}:focus-visible)`]: {
        ...theme.focusRing,
      },

      [`.${AIToolbarClasses.triggerLeading}`]: {
        display: "flex",
        alignItems: "center",
        marginInlineStart: theme.toRem(theme.spacing[16]),
        marginInlineEnd: theme.toRem(theme.spacing[16]),
        gap: theme.toRem(theme.spacing[8]),
        overflow: "hidden",
        borderRadius: theme.toRem(4),

        // Hide local focus ring because the parent (Trigger) handles the visual indication via :has()
        "&:focus-visible": {
          outline: "none",
        },

        "> svg": {
          flexShrink: 0,
        },
        ...styleSlots?.triggerLeading,
      },

      [`.${AIToolbarClasses.triggerTrailing}`]: {
        display: "flex",
        alignItems: "center",
        marginInlineStart: "auto",
        gap: theme.toRem(theme.spacing[8]),
        marginInlineEnd: theme.toRem(theme.spacing[16]),
        flexShrink: 0,
        "> svg": {
          marginInlineEnd: `calc(${theme.toRem(theme.spacing[4])} * -1)`,
        },
        ...styleSlots?.triggerTrailing,
      },

      svg: {
        color: theme.color.content.icon,
        fontSize: theme.toRem(16),
        ...styleSlots?.icon,
      },

      ...styleSlots?.trigger,
    },

    [`.${AIToolbarClasses.text}`]: {
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[4]),
      width: "fill-available",
      ...theme.typography.body.md,

      // Variant overrides
      '&[data-variant="bold"]': {
        ...theme.typography.body.mdAccent,
        ...styleSlots?.textBold,
      },
      '&[data-variant="emphasis"]': {
        color: theme.color.content.default,
        ...styleSlots?.textEmphasis,
      },
      '&[data-variant="emphasisBold"]': {
        color: theme.color.content.default,
        ...theme.typography.body.mdAccent,
        ...styleSlots?.textEmphasisBold,
      },
      ...styleSlots?.text,
    },

    [`.${AIToolbarClasses.textContent}`]: {
      overflow: "hidden",
      whiteSpace: "nowrap",
      minWidth: "fit-content",
      "&:last-of-type": {
        textOverflow: "ellipsis",
        minWidth: 0,
      },
      ...styleSlots?.textContent,
    },

    [`.${AIToolbarClasses.content}`]: {
      width: "100%",
      flex: 1,
      minHeight: 0,
      opacity: 0,
      transition: "opacity 0.1s ease-out",
      display: "flex",
      flexDirection: "column",
      overflow: "auto",
      borderRadius: theme.toRem(24),
      ...styleSlots?.content,
    },

    '&[data-state="collapsed"]': {
      maxHeight: theme.toRem(44),
      borderRadius: theme.toRem(24),

      [`.${AIToolbarClasses.trigger}`]: {
        opacity: 1,
        transition: "opacity 0.2s ease-in 0.1s",
      },

      [`.${AIToolbarClasses.content}`]: {
        opacity: 0,
        pointerEvents: "none",
        transition: "opacity 0.3s ease-out",
      },
      ...styleSlots?.collapsed,
    },

    '&[data-state="expanded"]': {
      width: theme.toRem(500),
      maxHeight: "calc(100% - 32px)",
      borderRadius: theme.toRem(16),
      cursor: "default",
      border: `${theme.border.width.sm} solid ${theme.color.border.default}`,

      [`.${AIToolbarClasses.trigger}`]: {
        opacity: 0,
        pointerEvents: "none",
        transition: "opacity 0.1s ease-out",
      },

      [`.${AIToolbarClasses.content}`]: {
        opacity: 1,
        transition: "opacity 0.3s ease-in-out 0.1s",
        borderRadius: theme.toRem(16),
      },
      ...styleSlots?.expanded,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledAIToolbar = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<AIToolbarProps>((props) => generateStyles(props));
